insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('MT', 'default', 'Malta reference chart of accounts (GAPSME horizontal layout)', '{}'::jsonb, true, 'companies', array['MT-GAPSME-BS', 'MT-GAPSME-IS']::text[], null, 'Malta prescribes no numbered chart of accounts. Companies Act (Cap. 386), article 167(1) requires accounts that give a true and fair view and comply with generally accepted accounting principles and practice; article 183 and the Accountancy Profession Act (Cap. 281) make GAPSME — the Accountancy Profession (General Accounting Principles for Small and Medium-Sized Entities) Regulations, S.L. 281.05 — the default financial reporting framework for a qualifying small or medium-sized entity, unless the board resolves to report under IFRS as adopted by the EU (S.L. 281.05, regulation 4) or the entity exceeds the size thresholds of regulation 5, in which case IFRS applies. This chart is original: its account blocks follow the balance sheet headings GAPSME §4.13 lists for the horizontal layout, so that the statements of this pack read straight off the chart.', 'gapsme')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

