insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('MT', 'MT-P-05-OVERHEAD', 'Purchase of services and overheads, reduced rate 5%', '{}'::jsonb, null, 'percent', 5, 'purchase', 'domestic', date '2004-05-01', null, 'Value Added Tax Act, Eighth Schedule [article 19(2)] and article 23. Box 32 carries the value and box 38 the input tax.', 'S', null, 270, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-P-05-RESALE', 'Purchase for re-sale, reduced rate 5%', '{}'::jsonb, null, 'percent', 5, 'purchase', 'domestic', date '2004-05-01', null, 'Value Added Tax Act, Eighth Schedule [article 19(2)] for the rate and article 23 for the right of deduction. Box 28 carries the value and box 35 the input tax.', 'S', null, 210, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-P-07-OVERHEAD', 'Purchase of services and overheads, reduced rate 7%', '{}'::jsonb, null, 'percent', 7, 'purchase', 'domestic', date '2004-05-01', null, 'Value Added Tax Act, Eighth Schedule [article 19(2)], items 1 and 11, and article 23. Box 31a carries the value and box 37a the input tax.', 'S', null, 250, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-P-12-OVERHEAD', 'Purchase of services and overheads, reduced rate 12%', '{}'::jsonb, null, 'percent', 12, 'purchase', 'domestic', date '2024-01-01', null, 'Value Added Tax Act, Eighth Schedule [article 19(2)], items 12 to 15, inserted by Legal Notice 231 of 2023 with effect from 1 January 2024, and article 23. Box 31b carries the value and box 37b the input tax.', 'S', null, 260, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ln-231-2023', null, null, null, null),
  ('MT', 'MT-P-18-OVERHEAD', 'Purchase of services and overheads, standard rate 18%', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2004-05-01', null, 'Value Added Tax Act, article 19(1) and article 23. Box 31 carries the value of services and overheads taxed at the standard rate and box 37 the input tax.', 'S', null, 240, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-P-18-RESALE', 'Purchase for re-sale, standard rate 18%', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2004-05-01', null, 'Value Added Tax Act, article 19(1) for the rate and article 23 for the right of deduction. Box 27 of the VAT Return carries the value of a taxable purchase for re-sale at the standard rate and box 34 the input tax.', 'S', null, 200, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-P-CAPITAL', 'Purchase of capital goods, standard rate 18%', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2004-05-01', null, 'Value Added Tax Act, article 23 and the Tenth Schedule (Deductions), which hold a capital good to a longer adjustment period than a current purchase, which is why the VAT Return reports it apart from ordinary purchases and overheads. Box 30 carries the value and box 36 the input tax.', 'S', null, 230, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-P-EXEMPT-RESALE', 'Purchase for re-sale, exempt supply', '{}'::jsonb, null, 'percent', 0, 'purchase', 'exempt', date '2004-05-01', null, 'Value Added Tax Act, Fifth Schedule — the supplier carries on an activity exempt with or without credit and charges no tax. Box 29 carries the value; there is no tax. `vat_category` is left null: the category on the invoice is the one the supplier chose, and this purchase-only tax does not record it.', null, null, 220, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-P-FSR', 'Service received from a supplier outside the European Union, standard rate 18%', '{}'::jsonb, null, 'percent', 18, 'purchase', 'foreign_services_received', date '2004-05-01', null, 'Value Added Tax Act, article 20(2)(b) read with the Third Schedule, Part Two, item 2(a) — the same self-assessment where the supplier is established outside the Union; article 23 gives the right to deduct it. The VAT Return has no box for a service received from another EU Member State outside boxes 3/9a/13a, so a service from a supplier outside the Union is carried in box 4 ("Goods and Services received where Place of Supply is Malta other than those reported in Box 3") and again in box 11, the self-assessed output tax in box 7 and its deduction in box 15.', null, null, 310, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-P-ICG', 'Intra-Community acquisition of goods, standard rate 18%', '{}'::jsonb, null, 'percent', 18, 'purchase', 'intracom_acquisition_goods', date '2004-05-01', null, 'Value Added Tax Act, article 4(b) and article 20(1)(b) — tax is charged on an intra-Community acquisition made for consideration and is a liability of the person who makes the acquisition; article 23 gives the right to deduct it in the same period. The VAT Return carries the value in box 3 ("IC Acquisitions of Goods and Services received from other EU Member States") and again in box 9 ("IC Acquisitions of Goods excluding Capital Goods"), the self-assessed output tax in box 6 and its deduction in box 13, so that a fully deductible acquisition nets to nothing.', 'K', 'VATEX-EU-IC', 280, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-P-ICG-CAPITAL', 'Intra-Community acquisition of capital goods, standard rate 18%', '{}'::jsonb, null, 'percent', 18, 'purchase', 'intracom_acquisition_goods', date '2004-05-01', null, 'Value Added Tax Act, article 4(b), article 20(1)(b) and the Tenth Schedule (Deductions), which holds a capital good to a longer adjustment period, which is why the VAT Return reports it apart from an ordinary intra-Community acquisition of goods. The value is carried in box 3 and again in box 10 ("IC Acquisitions of Capital Goods"), the self-assessed output tax in box 6 and its deduction in box 14.', 'K', 'VATEX-EU-IC', 290, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-P-ICS', 'Service received from a supplier in another Member State, standard rate 18%', '{}'::jsonb, null, 'percent', 18, 'purchase', 'intracom_acquisition_services', date '2004-05-01', null, 'Value Added Tax Act, article 20(2)(b) read with the Third Schedule, Part Two, item 2(a) — the tax on a service supplied by a person not established in Malta to a taxable person registered under article 10 is that person''s liability, self-assessed; article 23 gives the right to deduct it. The value is carried in box 3 and again in box 9a ("Services received from EU Member States where the purchaser is liable for VAT"), the self-assessed output tax in box 6 and its deduction in box 13a.', 'K', 'VATEX-EU-IC', 300, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-S-05', 'Sale, reduced rate 5%', '{}'::jsonb, null, 'percent', 5, 'sale', 'domestic', date '2004-05-01', null, 'Value Added Tax Act, Eighth Schedule [article 19(2)], items 2 to 10 — among them the supply of electricity (item 2), printed matter including e-books (item 5), the importation of works of art, collector''s items and antiques (item 7), minor repairs of bicycles, shoes and clothing (item 8), domestic care services (item 9) and admission to museums, art exhibitions, concerts and theatres (item 10). Box 19 carries the value and box 24 the tax.', 'S', null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-S-07', 'Sale, reduced rate 7% — accommodation and sporting facilities', '{}'::jsonb, null, 'percent', 7, 'sale', 'domestic', date '2004-05-01', null, 'Value Added Tax Act, article 19(2) and Eighth Schedule [article 19(2)], items 1 and 11 — licensed tourist accommodation and the use of sporting facilities are taxed at seven per cent. Box 18a carries the value and box 23a the tax.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-S-12', 'Sale, reduced rate 12% — securities, credit management, boat hire, body care', '{}'::jsonb, null, 'percent', 12, 'sale', 'domestic', date '2024-01-01', null, 'Value Added Tax Act, Eighth Schedule [article 19(2)], items 12 to 15, inserted by the Value Added Tax Act (Amendment of Eighth Schedule) Regulations, 2023 (Legal Notice 231 of 2023) with effect from 1 January 2024 — custody and management of securities; management of credit and credit guarantees by a person other than the one who granted the credit; the short-term hiring of a pleasure boat not exceeding five weeks over a running twelve-month period; and services consisting of the care of the human body delivered by a person exercising a profession regulated by the Health Care Professions Act, including a health studio, other than an exempt supply of item 11 of Part Two of the Fifth Schedule. Box 18b carries the value and box 23b the tax.', 'S', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ln-231-2023', null, null, null, null),
  ('MT', 'MT-S-18', 'Sale, standard rate 18%', '{}'::jsonb, null, 'percent', 18, 'sale', 'domestic', date '2004-05-01', null, 'Value Added Tax Act, article 19(1) — the tax chargeable on every taxable supply, other than a supply specified in the Eighth Schedule, is eighteen per cent of the taxable value of the supply. Box 18 of the VAT Return carries the value of a domestic supply taxed at the standard rate and box 23 the tax.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-S-EDUCATION', 'Sale, education — exempt without credit', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2004-05-01', null, 'Value Added Tax Act, article 9(1)(a) and Fifth Schedule, Part Two, item 12(1) — the provision of education or educational research, vocational training or retraining by a government school or institution, the University of Malta, a school registered under the Education Act, or an establishment the Commissioner recognises for the purpose, is exempt without credit. Box 21 carries the value; there is no tax and no right to deduct the tax incurred on the related purchases.', 'E', 'VATEX-EU-132-1I', 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-S-EXPORT', 'Export of goods outside the European Union', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2004-05-01', null, 'Value Added Tax Act, Fifth Schedule, Part One, item 1(1) — the supply of goods dispatched or transported to a destination outside the Community by or on behalf of the seller is exempt with credit. Box 20, "Exempt with Credit / Exports", carries the value.', 'G', 'VATEX-EU-G', 70, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-S-FINANCE', 'Sale, credit and financial services — exempt without credit', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2004-05-01', null, 'Value Added Tax Act, Fifth Schedule, Part Two, item 3 — the granting and negotiation of credit, transactions concerning deposit and current accounts, payments, currency and securities, and the management of a collective investment scheme, are exempt without credit. Box 21 carries the value.', 'E', 'VATEX-EU-135-1', 100, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-S-FOOD', 'Sale, food for human consumption — exempt with credit', '{}'::jsonb, null, 'percent', 0, 'sale', 'domestic', date '2004-05-01', null, 'Value Added Tax Act, Fifth Schedule, Part One, item 9 — the supply of food for human consumption, excluding food supplied in the course of catering, is exempt with credit. Box 20, "Exempt with Credit / Exports", carries the value; there is no tax.', 'Z', null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-S-ICG', 'Intra-Community supply of goods', '{}'::jsonb, null, 'percent', 0, 'sale', 'intracom_goods', date '2004-05-01', null, 'Value Added Tax Act, Fifth Schedule, Part One, item 3(1) — the intra-Community supply of goods to a person identified on the invoice by a valid and active value added tax identification number of a Member State other than Malta is exempt with credit, subject to the recapitulative statement of article 30(2). Box 1, "Exempt IC Supplies of Goods and Supplies of Services where customer is liable for the tax", carries the value.', 'K', 'VATEX-EU-IC', 120, 'vat', true, array['buyer_status', 'transport_evidence']::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-S-ICS', 'Services supplied to a taxable person in another Member State', '{}'::jsonb, null, 'percent', 0, 'sale', 'intracom_services', date '2004-05-01', null, 'Value Added Tax Act, Third Schedule, Part Two, item 2(a) [article 7] — the place of supply of a service to a taxable person acting as such is where that person is established, so a service supplied to a business in another Member State is outside the scope of Maltese VAT and the customer accounts for the tax under Articles 44 and 196 of Directive 2006/112/EC. Box 1, which the form describes as covering "Supplies of Services where customer is liable for the tax" alongside intra-Community goods, carries the value.', 'K', 'VATEX-EU-IC', 130, 'vat', true, array['buyer_status']::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-S-INSURANCE', 'Sale, insurance and reinsurance — exempt without credit', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2004-05-01', null, 'Value Added Tax Act, Fifth Schedule, Part Two, item 2 — the supply by a person licensed under the Insurance Business Act or the Insurance Distribution Act of insurance and reinsurance transactions, including related services specific to and essential for them, is exempt without credit. Box 21 carries the value.', 'E', 'VATEX-EU-135-1', 90, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-S-LETTING', 'Sale, letting of immovable property — exempt without credit', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2004-05-01', null, 'Value Added Tax Act, Fifth Schedule, Part Two, item 1(1) — the letting of immovable property is exempt without credit, excluding licensed tourist accommodation, designated parking, permanently installed equipment, a letting to a person registered under article 10 for the purpose of that person''s economic activity, and a letting of no more than thirty days, among other carve-outs the item lists. Box 21 carries the value.', 'E', 'VATEX-EU-135-1', 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MT', 'MT-S-PHARMA', 'Sale, pharmaceutical goods — exempt with credit', '{}'::jsonb, null, 'percent', 0, 'sale', 'domestic', date '2004-05-01', null, 'Value Added Tax Act, Fifth Schedule, Part One, item 10 — the supply of pharmaceutical goods is exempt with credit. Box 20 carries the value.', 'Z', null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null)
