on conflict (tax_template_id, document_kind, posting_type, sequence) do update set
  factor_percent     = excluded.factor_percent,
  account_code       = excluded.account_code,
  declaration_box    = excluded.declaration_box,
  declaration_boxes  = excluded.declaration_boxes,
  box_factor_percent = excluded.box_factor_percent,
  report_code        = excluded.report_code;

insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('MT', 'MT-VAT-RETURN', 'VAT Return', array['quarter']::declaration_period[], 'quarter'::declaration_period, date '2004-05-01', null, 'Value Added Tax Act, article 17(2) — except as otherwise provided, a tax period means a period of three calendar months commencing on the first day immediately following the end of the preceding tax period. Article 17(3) lets the Minister prescribe a different period by regulation for a class of persons; this pack carries no text naming such a regulation, so only the quarter the Act itself gives everybody is declared. Article 27(1) and (3) require the return to be furnished, either on the prescribed form or electronically through the Commissioner''s web portal, for every tax period. Box numbers and their layout are transcribed from a specimen of the form itself.', true,null, null, null, null, null, null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('MT', 'MT-VAT-RETURN', '1', 'base', 'Exempt IC Supplies of Goods and Supplies of Services where customer is liable for the tax', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, Fifth Schedule, Part One, item 3(1) (the intra-Community supply of goods) and article 20(2)(b) read with the Third Schedule, Part Two, item 2(a) (a service supplied to a taxable person established in another Member State, who accounts for the tax there). The VAT Return prints the two together in one box.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '2', 'base', 'Supplies of Goods and Services where Place of Supply is outside Malta - EU and Non EU', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, Third Schedule — the value of a supply whose place is not Malta and which is not already reported in box 1. This pack declares the box, which `ekwo pack check` requires of every reference in box 5, and posts no tax code to it: which of a pack''s treatments the Office of the Commissioner for Revenue means this box to carry, beyond the intra-Community case of box 1, could not be confirmed against an explanatory guide (cfr.gov.mt and mtca.gov.mt refused every automated request this pack''s authors made of them), so nothing is asserted about its scope beyond its own printed words.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '3', 'base', 'IC Acquisitions of Goods and Services received from other EU Member States', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, article 4(b) (intra-Community acquisitions of goods) and article 20(2)(b) (services received from a supplier in another Member State). The same value is carried again, split by kind, in boxes 9, 9a and 10 of the deduction section below.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '4', 'base', 'Goods and Services received where Place of Supply is Malta other than those reported in Box 3', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, article 20(2)(b) — a supply received from a person not established in Malta and not registered under article 10, whose place of supply is Malta, other than one already carried in box 3 (a supply from another Member State): a service received from a supplier outside the European Union. The same value is carried again in box 11.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '5', 'total', 'Sub-Total (Intra-Community and Non-EU Trade, value)', '{}'::jsonb, 50, null, array['1', '2', '3', '4']::text[], '{}'::text[], null, null, false, false, null, 'The value sub-total the form prints under the "Intra-Community and Non-EU Trade" heading.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '6', 'tax', 'Output tax self-assessed on IC Acquisitions of Goods and Services received from other EU Member States', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, article 20(1)(b) and article 20(2)(b) — the tax self-assessed by the person who makes the acquisition or receives the service, on the value of box 3.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '7', 'tax', 'Output tax self-assessed on Goods and Services received where Place of Supply is Malta', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, article 20(2)(b) — the tax self-assessed on the value of box 4.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '8', 'total', 'Sub-Total (Intra-Community and Non-EU Trade, output tax)', '{}'::jsonb, 80, null, array['6', '7']::text[], '{}'::text[], null, null, false, false, null, 'The output tax sub-total the form prints under the "Intra-Community and Non-EU Trade" heading.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '9', 'base', 'IC Acquisitions of Goods excluding Capital Goods', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The value of box 3 that is an acquisition of goods other than a capital good, repeated here for the deduction the person who made the acquisition is entitled to under article 23.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '9a', 'base', 'Services received from EU Member States where the purchaser is liable for VAT', '{}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The value of box 3 that is a service, repeated here for its deduction under article 23.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '10', 'base', 'IC Acquisitions of Capital Goods', '{}'::jsonb, 110, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The value of box 3 that is an acquisition of a capital good, repeated here for its deduction under article 23 and the Tenth Schedule (Deductions), which holds a capital good to a longer adjustment period.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '11', 'base', 'Goods and Services Received where Place of Supply is Malta', '{}'::jsonb, 120, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The value of box 4, repeated here for its deduction under article 23.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '12', 'total', 'Sub-Total (Deductions of Self-Charged VAT, value)', '{}'::jsonb, 130, null, array['9', '9a', '10', '11']::text[], '{}'::text[], null, null, false, false, null, 'The value sub-total the form prints under the "Deductions of Self-Charged VAT" heading.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '13', 'tax', 'Input tax deducted on IC Acquisitions of Goods excluding Capital Goods', '{}'::jsonb, 140, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, article 23 — the deduction of the tax self-assessed in box 6 that corresponds to box 9.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '13a', 'tax', 'Input tax deducted on Services received from EU Member States', '{}'::jsonb, 150, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, article 23 — the deduction corresponding to box 9a.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '14', 'tax', 'Input tax deducted on IC Acquisitions of Capital Goods', '{}'::jsonb, 160, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, article 23 and the Tenth Schedule — the deduction corresponding to box 10.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '15', 'tax', 'Input tax deducted on Goods and Services Received where Place of Supply is Malta', '{}'::jsonb, 170, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, article 23 — the deduction corresponding to box 11.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '16', 'total', 'Sub-Total (Deductions of Self-Charged VAT, input tax)', '{}'::jsonb, 180, null, array['13', '13a', '14', '15']::text[], '{}'::text[], null, null, false, false, null, 'The input tax sub-total the form prints under the "Deductions of Self-Charged VAT" heading.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '17', 'total', 'Net self-charged VAT', '{}'::jsonb, 190, null, array['8']::text[], array['16']::text[], null, null, false, false, null, 'The form prints "( 8 - 16 )" beside this box: the self-assessed output tax of box 8 less its deduction in box 16, carried into box 26.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '18', 'base', 'Taxable Goods/Services @ 18%', '{}'::jsonb, 200, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, article 19(1) — the value of a domestic supply at the standard rate.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '18a', 'base', 'Taxable Services @7%', '{}'::jsonb, 210, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, Eighth Schedule [article 19(2)], items 1 and 11 — the value of a domestic supply of services at 7%.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '18b', 'base', 'Taxable Services @12%', '{}'::jsonb, 220, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, Eighth Schedule [article 19(2)], items 12 to 15, inserted by Legal Notice 231 of 2023 — the value of a domestic supply of services at 12%.', 'ln-231-2023'),
  ('MT', 'MT-VAT-RETURN', '19', 'base', 'Taxable Goods/Services @ 5%', '{}'::jsonb, 230, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, Eighth Schedule [article 19(2)] — the value of a domestic supply of goods or services at 5%.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '20', 'base', 'Exempt with Credit / Exports', '{}'::jsonb, 240, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, Fifth Schedule, Part One — the value of a supply exempt with credit, among them the export of goods (item 1), food for human consumption (item 9) and pharmaceutical goods (item 10).', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '21', 'base', 'Exempt without Credit', '{}'::jsonb, 250, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, Fifth Schedule, Part Two — the value of a supply exempt without credit.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '22', 'total', 'Sub-Total (Domestic Supplies & Exports, value)', '{}'::jsonb, 260, null, array['18', '18a', '18b', '19', '20', '21']::text[], '{}'::text[], null, null, false, false, null, 'The value sub-total the form prints under the "Domestic Supplies & Exports" heading.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '23', 'tax', 'Output tax on Taxable Goods/Services @ 18%', '{}'::jsonb, 270, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The tax on box 18.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '23a', 'tax', 'Output tax on Taxable Services @7%', '{}'::jsonb, 280, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The tax on box 18a.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '23b', 'tax', 'Output tax on Taxable Services @12%', '{}'::jsonb, 290, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The tax on box 18b.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '24', 'tax', 'Output tax on Taxable Goods/Services @ 5%', '{}'::jsonb, 300, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The tax on box 19.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '25', 'total', 'Sub-Total output tax (Domestic Supplies & Exports)', '{}'::jsonb, 310, null, array['23', '23a', '23b', '24']::text[], '{}'::text[], null, null, false, false, null, 'The form prints "( 23 + 23a + 23b + 24 )" beside this box.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '26', 'total', 'Total output tax', '{}'::jsonb, 320, null, array['17', '25']::text[], '{}'::text[], null, null, false, false, null, 'The form prints "( 17 + 25 )" beside this box: the net self-charged VAT of box 17 plus the domestic output tax of box 25.', 'cfr-vat-return'),
