  ('MT', 'MT-VAT-RETURN', '39', 'total', 'Total input tax', '{}'::jsonb, 490, null, array['34', '35', '36', '37', '37a', '37b', '38']::text[], '{}'::text[], null, null, false, false, null, 'The form prints "(34 +35 +36 +37 +37a + 37b +38)" beside this box.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '40', 'tax', 'Adjustment in favour of the Department', '{}'::jsonb, 500, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'A manual adjustment the form allows and no code of this pack posts: it is a correction the filer enters by hand, not a fact the ledger states. It reads zero in a return this pack has never had reason to adjust.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '41', 'tax', 'Adjustment in favour of the taxpayer', '{}'::jsonb, 510, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The same, in the taxpayer''s favour.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '42', 'total', 'Excess Credit', '{}'::jsonb, 520, null, array['39', '41']::text[], array['26', '40']::text[], null, null, true, false, null, 'The form prints "(39 - 26) + (41 - 40)" beside this box, floored at zero: the amount by which deductible tax exceeds tax due, before any credit brought forward from an earlier period.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '43', 'total', 'Net tax due before credit brought forward', '{}'::jsonb, 530, null, array['26', '40']::text[], array['39', '41']::text[], null, null, true, false, null, 'The form prints "(26 - 39) + (40 - 41)" beside this box, floored at zero, with no printed name of its own: the amount by which tax due exceeds deductible tax, before any credit brought forward.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '44', 'tax', 'Excess Credit brought forward', '{}'::jsonb, 540, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'The credit a person carries from an earlier tax period, printed on the form and settled against box 43. No code of this pack posts to it — a balance brought forward from a prior return is not a fact this period''s ledger states — and the golden scenario of this pack never reaches a period where one is owed, so it reads zero throughout.', 'cfr-vat-return'),
  ('MT', 'MT-VAT-RETURN', '45', 'total', 'Tax Payable', '{}'::jsonb, 550, null, array['43']::text[], array['44']::text[], null, null, true, false, null, 'The form prints "( 43 - 44 )" beside this box.', 'cfr-vat-return')
