insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('MT-GAPSME-BS', 'MT', 'default', 'Balance Sheet — GAPSME horizontal layout', 'balance_sheet', 'MT-GAPSME', date '1970-01-01', null, 'Accountancy Profession (General Accounting Principles for Small and Medium-Sized Entities) Regulations (S.L. 281.05), Section 4, paragraph 4.13 — the horizontal layout of the balance sheet, one of the two layouts an entity may adopt. Every heading and sub-item below is the format''s own wording; items preceded by Arabic numerals may be combined when immaterial or for clarity, which paragraph 4.13 itself permits and which this chart does in a few places noted beside the line.', 'gapsme'),
  ('MT-GAPSME-IS', 'MT', 'default', 'Income Statement — GAPSME, function of expense method', 'income_statement', 'MT-GAPSME', date '1970-01-01', null, 'Accountancy Profession (General Accounting Principles for Small and Medium-Sized Entities) Regulations (S.L. 281.05), Section 4, paragraphs 4.21 and 4.22 — an entity classifies its expenses by nature or by function, whichever is reliable and more relevant; this pack transcribes the function-of-expense method. Items 7 and 8 of paragraph 4.22 — income under the cost method and the equity method from shares in subsidiaries, associates and jointly controlled entities — are combined on one line of this chart, which paragraph 4.21 itself permits where items may be combined for clarity.', 'gapsme')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

