update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = 30,
  late_payment_reference        = 'Commercial Code (Cap. 13), Title II-A (Of Late Payment in Commercial Transactions), inserted by Legal Notice 272 of 2012 transposing Directive 2011/7/EU — thirty calendar days from receipt of the goods or services, or of the invoice if later, in the absence of an agreed term; statutory interest at the European Central Bank''s main refinancing rate plus eight percentage points (10.15% from 1 July 2025), and a fixed minimum compensation of €40 for recovery costs',
  numbering_legal_reference     = 'Value Added Tax Act, Twelfth Schedule [article 50(5)], item 3 — every tax invoice carries "a sequential number, based on one or more series, which uniquely identifies the invoice". The text requires a sequence, series and uniqueness and prescribes no shape and no rule against a hole, which is why `numbering` is `sequential` rather than gapless.',
  numbering_source_key          = 'vat-act',
  payment_terms_legal_reference = 'Commercial Code (Cap. 13), Title II-A, inserted by Legal Notice 272 of 2012 — where the contract fixes no date, the debtor is in default, and interest starts to run, thirty calendar days after the later of the receipt of the goods or services and the receipt of the invoice.',
  payment_terms_source_key      = 'commercial-code',
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'Value Added Tax Act, Fourth Schedule [article 8], item 3 — the tax on a supply becomes chargeable on the earlier of the date of the chargeable event (delivery of the goods or performance of the services, item 1 and item 2) and the date a payment is made for the supply, to the extent covered by that payment; a proviso brings the date forward to that of a tax invoice issued by the fifteenth day of the month following, which this pack does not model separately — a tax that departs from the general rule says so through `cash_basis`, and this pack declares none.',
  tax_point_source_key          = 'vat-act',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = 'peppol-bis-3',
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'No Maltese statute obliges a business to issue a structured electronic invoice to another business today, so `obligation` is `none` and `mandatory_from` is empty. A contracting authority must be able to receive and process an EN 16931 invoice under the European Union (public procurement) electronic invoicing rules; that is an obligation of the public buyer, not of the supplier, and this pack carries no separate field for it. The EU''s VAT in the Digital Age package will require structured, EN 16931-based invoicing for intra-Union cross-border business-to-business supplies from 1 July 2030, and Malta''s own tax administration has signalled work on a national e-invoicing and digital reporting regime ahead of that date, but at the day this pack was released no Maltese legal notice had set a date or a mandatory profile. The profile declared is Peppol BIS Billing 3.0, which is what Peppol participants in Malta exchange today, and is not a legal requirement. The two identifiers are ISO 6523 codes of the Peppol electronic address scheme list: 0088 is the Global Location Number, because that list carries no code for a Malta Business Registry company number; 9943 is the Malta VAT number.',
  einvoice_source_key           = 'peppol-eas',
  party_scheme                  = '0088',
  vat_scheme                    = '9943',
  bank_statement_formats        = array['camt.053']::text[],
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'MT';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('MT', 'intracom_goods', 'intra_eu_goods', 'Intra-Community supply of goods — exempt with credit under item 3, Part One of the Fifth Schedule to the Value Added Tax Act (Article 138 of Directive 2006/112/EC).', '{}'::jsonb, 10, date '1970-01-01', null, 'Value Added Tax Act, Fifth Schedule, Part One, item 3(1) — the intra-Community supply of goods to a person identified on the invoice by a valid value added tax identification number of another Member State is exempt with credit, subject to the recapitulative statement of article 30(2).'),
  ('MT', 'intracom_services', 'intra_eu_services', 'Reverse charge — the customer is liable to account for the VAT (Articles 44 and 196 of Directive 2006/112/EC).', '{}'::jsonb, 20, date '1970-01-01', null, 'Value Added Tax Act, article 20(2)(b) read with the Third Schedule, Part Two, item 2(a) — the place of a service supplied to a taxable person is where that person is established, so the payment of the tax on a service supplied to a taxable person identified for VAT in another Member State is that person''s liability.'),
  ('MT', 'export', 'export', 'Export of goods outside the European Union — exempt with credit under item 1, Part One of the Fifth Schedule to the Value Added Tax Act.', '{}'::jsonb, 30, date '1970-01-01', null, 'Value Added Tax Act, Fifth Schedule, Part One, item 1 — the supply of goods dispatched or transported to a destination outside the Community by or on behalf of the seller, or by or on behalf of a purchaser not established in Malta, is exempt with credit.'),
  ('MT', 'exempt', 'exempt', 'Exempt from VAT under the Fifth Schedule to the Value Added Tax Act.', '{}'::jsonb, 40, date '1970-01-01', null, 'Value Added Tax Act, article 9(1) and the Fifth Schedule — the supplies to which Part One (exempt with credit) or Part Two (exempt without credit) of the Fifth Schedule applies are exempt from tax.'),
  ('MT', 'late_payment', 'late_payment', 'If this invoice is not paid within the term stated, statutory interest and a fixed minimum compensation of €40 for recovery costs are due under the Commercial Code (Cap. 13), Title II-A.', '{}'::jsonb, 50, date '1970-01-01', null, 'Commercial Code (Cap. 13), Title II-A, inserted by Legal Notice 272 of 2012.')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
